bool img_transpose=false;

// What a snapshot consists of, per verdict.
//
// It used to be two bools -- "save NG" and "save NA" -- and each of them meant
// "write BOTH the .jpg and the .xreps". Measured on the bench, that is 146 KB
// per part (103 KB image + 43 KB report) at ~11 parts/s into a folder that
// keeps 8 files: ~138 GB a day written to retain 1.2 MB. Almost every byte of
// it is deleted within a second by removeOldestRep().
//
// The image is 70% of that and is also the half that is rarely the evidence:
// a report says what the machine decided, an image says what it saw. Being
// able to keep one without the other is what makes routine NG evidence
// affordable, so the policy is per verdict AND per part.
//
// EVERYTHING defaults to off. A machine should write to its disk because
// someone asked it to, not because nobody turned it off -- and the failure
// mode of the old defaults was silent, continuous and measured in hundreds of
// gigabytes a day. The screen pushes the configured policy on entering
// inspection, so an operator who wants evidence gets it from one place.
struct SnapPolicy { bool img; bool rep; };
static SnapPolicy g_snap_policy[3] = {
  /* OK */ { false, false },
  /* NG */ { false, false },
  /* NA */ { false, false },
};
enum SnapVerdict { SNAPV_OK = 0, SNAPV_NG = 1, SNAPV_NA = 2 };

// Which bucket a frame's inspection status falls in. UNSET is counted as NA:
// a frame nothing could judge is the same evidence question as one that failed
// to locate.
static SnapVerdict snap_verdict_of(int finspStatus)
{
  if (finspStatus == FeatureReport_sig360_circle_line_single::STATUS_FAILURE) return SNAPV_NG;
  if (finspStatus == FeatureReport_sig360_circle_line_single::STATUS_SUCCESS) return SNAPV_OK;
  return SNAPV_NA;
}
static bool snap_wants_anything(SnapVerdict v) { return g_snap_policy[v].img || g_snap_policy[v].rep; }
static bool frame_ring_active();

// ---------------------------------------------------------------------------
// The last N frames, in shared memory, for a core that has already died.
//
// The disk snapshot path answers "keep routine evidence"; it defaults to off
// because it wrote ~138 GB a day to retain a megabyte. This ring answers the
// other question -- "the core just died, what was it looking at" -- and it
// answers it without touching a disk while the machine is healthy.
//
// inspd_log is a separate process with parent-death detection that already
// writes crash_<utc>.dump. It attaches this region and writes the frames out
// beside that dump. See logctrl/include/frame_ring.h for the layout and the
// tear protocol.
//
// Off by default via INSP_FRAME_RING=0; sized by INSP_FRAME_RING_SLOTS.
static void *g_frame_ring = NULL;
static uint64_t g_frame_id = 0;
static bool frame_ring_active() { return g_frame_ring != NULL; }

static void frame_ring_open()
{
  if (const char *e = getenv("INSP_FRAME_RING"); e && *e == '0') return;

  uint32_t slots = FRAME_RING_SLOTS_DEFAULT;
  if (const char *e = getenv("INSP_FRAME_RING_SLOTS"))
  {
    int n = atoi(e);
    // Below 4 the ring cannot outrun a writer mid-crash; above 256 it is a
    // gigabyte of shared memory for a question that only ever needs seconds.
    if (n >= 4 && n <= 256) slots = (uint32_t)n;
  }

  // Same naming convention as the modules region: "<log ring>_frames".
  std::string name = "insp_log_ring";
  if (const char *e = getenv("INSP_LOG_RING_NAME")) name = e;
  name += "_frames";

  size_t need = frame_ring_total_bytes(slots);
  ShareMemoryInfo info = {};
  if (connSharedMemory(name, need, &info) != 0)
  {
    if (createSharedMemory(name, need, &info) != 0)
    {
      LOGE("frame ring: shm '%s' (%zu bytes) unavailable -- crash frames will not be captured",
           name.c_str(), need);
      return;
    }
  }
  if (!info.ptr) return;

  FrameRingHeader *h = static_cast<FrameRingHeader *>(info.ptr);
  // Re-initialise unless an identically shaped ring is already there. A stale
  // region from a previous run with a different slot count must not be read
  // with this run's geometry.
  if (h->magic != FRAME_RING_MAGIC || h->version != FRAME_RING_VERSION ||
      h->slot_size != FRAME_SLOT_BYTES || h->slot_count != slots)
  {
    memset(h, 0, sizeof(FrameRingHeader));
    h->magic = FRAME_RING_MAGIC;
    h->version = FRAME_RING_VERSION;
    h->slot_size = FRAME_SLOT_BYTES;
    h->slot_count = slots;
    h->head.store(0, std::memory_order_release);
  }
  g_frame_ring = info.ptr;
  LOGI("frame ring: '%s' %u slots x %u KB (%zu KB)", name.c_str(), slots,
       FRAME_SLOT_BYTES / 1024, need / 1024);
}

// Encode + copy one frame into the ring. Called from the snapshot thread, NOT
// from the inspection path: JPEG encoding is the expensive half and it has no
// business on a thread that decides parts.
static void frame_ring_push(const cv::Mat &image, cJSON *report_json, int finspStatus)
{
  if (!g_frame_ring) return;

  // Printed HERE, and freed here, so the caller cannot leak it by being
  // careless -- and so nothing is printed at all when the ring is off.
  // Unformatted: this is bytes in a crash dump, not something to read raw.
  char *rep = report_json ? cJSON_PrintUnformatted(report_json) : NULL;
  struct _RepHold { char *p; ~_RepHold(){ if (p) free(p); } } _rephold{rep};

  std::vector<uchar> jpg;
  if (!image.empty())
  {
    // Quality 80: this is forensics, not measurement. The report carries the
    // numbers; the image only has to show a human what was in front of the
    // camera.
    static const std::vector<int> params = { cv::IMWRITE_JPEG_QUALITY, 80 };
    try { cv::imencode(".jpg", image, jpg, params); }
    catch (const std::exception &e) { LOGE_EVERY_N(100, "frame ring: encode failed: %s", e.what()); jpg.clear(); }
  }

  const size_t rep_len = rep ? strlen(rep) : 0;
  size_t img_len = jpg.size();
  // The report is the half worth keeping when both will not fit: it says what
  // the machine decided. Drop the image rather than the report, and say so.
  if (img_len + rep_len > FRAME_PAYLOAD_MAX)
  {
    LOGW_EVERY_N(100, "frame ring: payload %zu > %u -- dropping the image half",
                 img_len + rep_len, FRAME_PAYLOAD_MAX);
    img_len = 0;
  }
  if (img_len + rep_len > FRAME_PAYLOAD_MAX) return;  // report alone too big

  FrameRingHeader *h = static_cast<FrameRingHeader *>(g_frame_ring);
  uint64_t idx = h->head.load(std::memory_order_relaxed);
  FrameSlot *sl = frame_ring_slot(g_frame_ring, idx);

  // Odd while writing: a reader that sees this discards the slot. This is the
  // whole point -- the producer may stop mid-memcpy, and a half-written JPEG
  // that looks valid is worse than a missing one.
  uint64_t seq = sl->seq.load(std::memory_order_relaxed);
  sl->seq.store(seq | 1, std::memory_order_release);

  sl->ts_ms = (uint64_t)current_time_ms();
  sl->frame_id = ++g_frame_id;
  sl->verdict = (uint32_t)snap_verdict_of(finspStatus);
  sl->img_len = (uint32_t)img_len;
  sl->rep_len = (uint32_t)rep_len;
  if (img_len) memcpy(sl->payload, jpg.data(), img_len);
  if (rep_len) memcpy(sl->payload + img_len, rep, rep_len);

  sl->seq.store((seq | 1) + 1, std::memory_order_release);
  h->head.store(idx + 1, std::memory_order_release);
}

// atomic, like every other drop counter here. It was a plain int written from
